output_text:
[
  {
    "id": "no_carts_single_file_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles where shelves flank both sides of the shopper.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "A shopper must not move into a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "hands_only_in_single_file_shelf_aisle",
    "text": "Items in single-file shelf aisles must be handled without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_narrow_aisle_item",
    "text": "After collecting an item while away from the cart in a single-file shelf aisle, the shopper must retrieve the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "noCartSingleFileShelfInteraction": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "noCartSingleFileShelfInteraction",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "retrieve_after_parking_cart",
    "text": "Whenever a shopper parks or releases a cart, they must later retrieve a cart before exiting.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "park_cart_only_at_aisle_mouth",
    "text": "Carts may only be parked at designated wide-mouth entrances to single-file aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisleMouth": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "singleFileAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_at_open_shelf_faces",
    "text": "At cart-accessible open shelf faces, shoppers should keep their cart with them while interacting with shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartAccessibleShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfFace",
          {
            "not": "hasCart"
          },
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "one_way_wide_horizontal_aisles",
    "text": "Wide horizontal travel aisles are one-way, so shoppers should not move west along them.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideHorizontalAisle",
          "W"
        ]
      }
    }
  }
]
